"""Brand images as base64 so the repo stays text-only (no binary uploads).

Run `python3 tools/brand_assets.py` after cloning to materialize docs/brand/*
before `pywrangler deploy` (wrangler serves [assets] directory ./docs).
Hashes below pin the approved bytes - regenerate nothing.
"""
import base64, hashlib, pathlib, sys

ROOT = pathlib.Path(__file__).resolve().parent.parent / "docs" / "brand"

FILES = {
    "avatar.png": ("eac57f003d4acbb7e47a63e8b71e3d4487db04025c850d3521bfcc6670001949",
        ""),
    "magpie.jpg": ("1dc0106444d4d50d84c9b54db3642e9523bfdfbf25e486b182e679001c2b60a1",
        ""),
    "mark.png": ("ae7639083252592704049ce4fc70d8d30989e7348e1a1cef977838e8153f71d2",
        ""),
    "og.png": ("89123fdff543dc706881dbe26d00187829ffebec3ba71dd10943372e6ac21ca9",
        ""),
    "seal.png": ("022fb022d74fe18e3b07e988713b0b5e78f3483570e37b57d4c5b2315c03b44c",
        ""),
}

def main():
    ROOT.mkdir(parents=True, exist_ok=True)
    for name, (sha, b64) in FILES.items():
        data = base64.b64decode(b64)
        assert hashlib.sha256(data).hexdigest() == sha, name
        (ROOT / name).write_bytes(data)
        print("wrote", name, len(data), "bytes")

if __name__ == "__main__":
    main()
